CREATE TABLE IF NOT EXISTS mailboxes(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,email TEXT,host TEXT,port INTEGER,secure INTEGER DEFAULT 1,username TEXT,pass_enc TEXT,daily_cap INTEGER DEFAULT 20,paused INTEGER DEFAULT 0,next_at INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS leads(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE COLLATE NOCASE,first_name TEXT,last_name TEXT,company TEXT,website TEXT,role TEXT,source TEXT,note TEXT,status TEXT DEFAULT 'new',added INTEGER);
CREATE TABLE IF NOT EXISTS campaigns(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,mailbox_id INTEGER,steps TEXT,tz TEXT,start_hour INTEGER,end_hour INTEGER,days TEXT,gap_min INTEGER,gap_max INTEGER,custom_from_name TEXT,custom_from_email TEXT,status TEXT DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS cl(id INTEGER PRIMARY KEY AUTOINCREMENT,campaign_id INTEGER,lead_id INTEGER,step INTEGER DEFAULT 0,next_at INTEGER,status TEXT DEFAULT 'active',tries INTEGER DEFAULT 0,UNIQUE(campaign_id,lead_id));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,ts INTEGER,day TEXT,mailbox_id INTEGER,cl_id INTEGER,type TEXT,detail TEXT);
CREATE TABLE IF NOT EXISTS suppression(email TEXT PRIMARY KEY COLLATE NOCASE,reason TEXT,ts INTEGER);
CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY,v TEXT);
CREATE INDEX IF NOT EXISTS ix_cl_due ON cl(campaign_id,status,next_at);
CREATE INDEX IF NOT EXISTS ix_ev ON events(mailbox_id,day,type);
CREATE TABLE IF NOT EXISTS tests(id INTEGER PRIMARY KEY AUTOINCREMENT,mailbox_id INTEGER,to_addr TEXT,status TEXT DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY AUTOINCREMENT,ts INTEGER,mailbox_id INTEGER,to_addr TEXT,subject TEXT,body TEXT,kind TEXT,step INTEGER,status TEXT,detail TEXT);
CREATE INDEX IF NOT EXISTS ix_out ON outbox(status,id);
